<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany}; class PurchaseOrder extends Model {protected $fillable=['order_number','supplier_id','warehouse_id','status','order_date','expected_date','discount','subtotal','total_amount','currency','notes','created_by']; protected $casts=['order_date'=>'date','expected_date'=>'date','discount'=>'decimal:2','subtotal'=>'decimal:2','total_amount'=>'decimal:2']; public function supplier():BelongsTo{return $this->belongsTo(Supplier::class);} public function warehouse():BelongsTo{return $this->belongsTo(Warehouse::class);} public function creator():BelongsTo{return $this->belongsTo(User::class,'created_by');} public function lines():HasMany{return $this->hasMany(PurchaseOrderLine::class);} }